    {{- $coverImage := .Resources.GetMatch "cover*" -}}
    {{- if $coverImage -}}
      <a href="{{- .Permalink -}}" title="{{- .Title -}}">
        <img src="{{- ($coverImage.Resize "600x").RelPermalink -}}" alt="{{- .Title -}}">
      </a>
    {{- end -}}
